export class Product {
  id: string;
  productName: string;
  categoryName: string;
  branchName: string;
  quantity: number;
  sold: number;
  price: number;
  shortDesc: string;
  detailsDesc: string;
  imageUrl?: string; // For frontend display purposes

  constructor(
    id: string = '',
    productName: string = '',
    categoryName: string = '',
    branchName: string = '',
    quantity: number = 0,
    sold: number = 0,
    price: number = 0,
    shortDesc: string = '',
    detailsDesc: string = '',
    imageUrl: string = ''
  ) {
    this.id = id;
    this.productName = productName;
    this.categoryName = categoryName;
    this.branchName = branchName;
    this.quantity = quantity;
    this.sold = sold;
    this.price = price;
    this.shortDesc = shortDesc;
    this.detailsDesc = detailsDesc;
    this.imageUrl = imageUrl;
  }
}

export interface ProductFormResponseDTO {
  id: string;
  productName: string;
  categoryName: string;
  branchName: string;
  quantity: number;
  sold: number;
  price: number;
  shortDesc: string;
  detailsDesc: string;
}
